<div id="page-content" class="page-wrapper clearfix grid-button"><div class="card"><div class="page-title clearfix"><h4><i data-feather="truck" class="icon-16"></i> Proveedores</h4><?php if($can_manage): ?><div class="title-button-group"><?php echo modal_anchor(get_uri('suppliers/modal_form'),'<i data-feather="plus-circle" class="icon-16"></i> Nuevo proveedor',['class'=>'btn btn-default','title'=>'Nuevo proveedor']); ?></div><?php endif; ?></div><div class="card-body"><div class="table-responsive"><table id="suppliers-table" class="display" width="100%"></table></div></div></div></div>
<script>$(function(){var table=$('#suppliers-table').appTable({source:'<?php echo_uri('suppliers/list_data'); ?>',columns:[{title:'Proveedor'},{title:'RFC'},{title:'Contacto'},{title:'Teléfono'},{title:'Correo'},{title:'Estado'},{title:'Acciones',class:'text-center option'}]});$(document).on('click','.supplier-toggle',function(){appAjaxRequest({url:'<?php echo get_uri('suppliers/toggle_status'); ?>',type:'POST',data:{id:$(this).data('id'),<?php echo json_encode(csrf_token()); ?>:<?php echo json_encode(csrf_hash()); ?>},success:function(r){appAlert.success(r.message,{duration:2000});table.appTable({reload:true});}});});});</script>
